namespace Iamshoaibktk\Geolens\Tests;

use Iamshoaibktk\Geolens\Bots\Registry;
use Iamshoaibktk\Geolens\Robots\Block;
use Iamshoaibktk\Geolens\Robots\Parser;
use PHPUnit\Framework\TestCase;

final class RobotsTest extends TestCase
{
    private const PRESTASHOP = <<<'TXT'
# robots.txt automatically generated by PrestaShop e-commerce open-source solution
User-agent: *

# Allow directives for modules
Allow: */modules/*.css
Allow: */modules/*.js
Allow: /js/jquery/*

# Non-friendly URLs and parameters blocked from crawling
Disallow: /*?order=
Disallow: /*?q=
Disallow: /*&q=
Disallow: /*controller=cart

# Rules for /
Disallow: /modules/
Disallow: /en/cart
Disallow: /cart

# Sitemap
Sitemap: https://shop.example/1_index_sitemap.xml

TXT;

    /** @dataProvider rfcCases */
    public function testRfcPrecedence(string $robots, string $token, string $path, bool $expected): void
    {
        $this->assertSame($expected, Parser::isAllowed(Parser::parse($robots), $token, $path));
    }

    public static function rfcCases(): array
    {
        return [
            'no file means allowed' => ['', 'GPTBot', '/x', true],
            'star group applies when not named' => ["User-agent: *\nDisallow: /x", 'GPTBot', '/x', false],
            'own group replaces the star group' => ["User-agent: *\nDisallow: /x\n\nUser-agent: GPTBot\nDisallow: /y", 'GPTBot', '/x', true],
            'token is case insensitive' => ["User-agent: gptbot\nDisallow: /", 'GPTBot', '/x', false],
            'consecutive agents share a group' => ["User-agent: A\nUser-agent: B\nDisallow: /", 'B', '/x', false],
            'same token merges' => ["User-agent: A\nDisallow: /x\n\nUser-agent: A\nDisallow: /y", 'A', '/y', false],
            'longest match wins' => ["User-agent: *\nDisallow: /a\nAllow: /a/b", 'X', '/a/b', true],
            'allow wins a tie' => ["User-agent: *\nDisallow: /a\nAllow: /a", 'X', '/a', true],
            'empty disallow restricts nothing' => ["User-agent: *\nDisallow:", 'X', '/a', true],
            'wildcard' => ["User-agent: *\nDisallow: /*?q=", 'X', '/1-women?q=Size-S', false],
            'wildcard does not over match' => ["User-agent: *\nDisallow: /*?q=", 'X', '/1-women', true],
            'end anchor' => ["User-agent: *\nDisallow: /*.pdf$", 'X', '/a.pdf', false],
            'end anchor keeps longer paths' => ["User-agent: *\nDisallow: /*.pdf$", 'X', '/a.pdf.html', true],
            'robots.txt is always readable' => ["User-agent: *\nDisallow: /", 'X', '/robots.txt', true],
            'comments are ignored' => ["User-agent: * # all\nDisallow: /a # no", 'X', '/a', false],
            'other fields do not end a group' => ["User-agent: *\nSitemap: https://x/s.xml\nDisallow: /a", 'X', '/a', false],
            'CRLF line ends' => ["User-agent: *\r\nDisallow: /a\r\n", 'X', '/a', false],
            'rules before any agent are ignored' => ["Disallow: /a\nUser-agent: *\nDisallow: /b", 'X', '/a', true],
        ];
    }

    public function testPrestashopRulesApplyToUnnamedBots(): void
    {
        $groups = Parser::parse(self::PRESTASHOP);
        $this->assertFalse(Parser::isAllowed($groups, 'OAI-SearchBot', '/cart'));
        $this->assertFalse(Parser::isAllowed($groups, 'OAI-SearchBot', '/1-women?q=Size-S'));
        $this->assertTrue(Parser::isAllowed($groups, 'OAI-SearchBot', '/3-shirts/1-tee.html'));
    }

    public function testBareAllowGroupIsReportedAsBypass(): void
    {
        $robots = self::PRESTASHOP . "\nUser-agent: GPTBot\nAllow: /\n";
        $groups = Parser::parse($robots);
        // The trap this method exists for: GPTBot may now crawl the cart and every filter URL.
        $this->assertTrue(Parser::isAllowed($groups, 'GPTBot', '/cart'));
        $this->assertSame(['gptbot'], Parser::bypassingGroups($groups));
    }

    public function testFullBlockIsNotABypass(): void
    {
        $this->assertSame([], Parser::bypassingGroups(Parser::parse(self::PRESTASHOP . "\nUser-agent: GPTBot\nDisallow: /\n")));
    }

    public function testTheModulesOwnBlockIsNeverABypass(): void
    {
        // The training opt-out writes "User-agent: Google-Extended / Allow: /", which is not a trap
        // because that token never crawls. Reading the file without the block must find nothing.
        $robots = Block::apply(self::PRESTASHOP, Block::build([], true, false));
        $this->assertContains('google-extended', Parser::bypassingGroups(Parser::parse($robots)));
        $this->assertSame([], Parser::bypassingGroups(Parser::parse(Block::strip($robots))));
    }

    public function testNoBypassWhenTheShopHasNoRules(): void
    {
        $this->assertSame([], Parser::bypassingGroups(Parser::parse("User-agent: GPTBot\nAllow: /\n")));
    }

    public function testVisibilityFirstWritesNothing(): void
    {
        $this->assertSame('', Block::build([], false, false));
    }

    public function testAllowedBotsNeverGetTheirOwnGroup(): void
    {
        $block = Block::build(['GPTBot'], false, false);
        $groups = Parser::parse(Block::apply(self::PRESTASHOP, $block));
        $this->assertFalse(Parser::isAllowed($groups, 'GPTBot', '/3-shirts/1-tee.html'));
        // OAI-SearchBot has no group, so it still obeys the shop's rules and can read products.
        $this->assertTrue(Parser::isAllowed($groups, 'OAI-SearchBot', '/3-shirts/1-tee.html'));
        $this->assertFalse(Parser::isAllowed($groups, 'OAI-SearchBot', '/cart'));
        $this->assertArrayNotHasKey('oai-searchbot', $groups);
    }

    public function testSearchEnginesCanNeverBeWritten(): void
    {
        $block = Block::build(['Googlebot', 'bingbot', 'Storebot-Google', 'Applebot'], false, false);
        $this->assertSame('', $block);
    }

    public function testUnknownTokensAreDropped(): void
    {
        $this->assertSame('', Block::build(["Evil\nDisallow: /"], false, false));
    }

    public function testTrainingOptOutKeepsGeminiGroundingExplicit(): void
    {
        $block = Block::build([], true, false);
        $this->assertStringContainsString("User-agent: __usage_ai-training\nDisallow: /", $block);
        $this->assertStringContainsString("User-agent: Google-Extended\nAllow: /", $block);
    }

    public function testBlockingGoogleExtendedRemovesTheExplicitAllow(): void
    {
        $block = Block::build(['Google-Extended'], true, false);
        $this->assertStringNotContainsString('Allow: /', $block);
        $this->assertFalse(Parser::isAllowed(Parser::parse($block), 'Google-Extended', '/'));
    }

    public function testContentSignals(): void
    {
        $this->assertStringContainsString('Content-Signal: search=yes, ai-input=yes, ai-train=no', Block::build([], true, true));
        $this->assertStringContainsString('Content-Signal: search=yes, ai-input=yes, ai-train=yes', Block::build([], false, true));
        $this->assertStringContainsString('ai-input=no', Block::build(Registry::presetBlocks('lockdown'), true, true));
    }

    public function testSignalsDoNotAddRulesToTheStarGroup(): void
    {
        $block = Block::build([], true, true);
        $groups = Parser::parse(Block::apply(self::PRESTASHOP, $block));
        $this->assertFalse(Parser::isAllowed($groups, 'Googlebot', '/cart'));
        $this->assertTrue(Parser::isAllowed($groups, 'Googlebot', '/3-shirts/1-tee.html'));
    }

    public function testApplyIsRepeatable(): void
    {
        $block = Block::build(['GPTBot'], false, false);
        $once = Block::apply(self::PRESTASHOP, $block);
        $this->assertSame($once, Block::apply($once, $block));
        $this->assertSame(1, substr_count($once, Block::BEGIN));
    }

    public function testApplyReplacesAnEarlierBlock(): void
    {
        $first = Block::apply(self::PRESTASHOP, Block::build(['GPTBot'], false, false));
        $second = Block::apply($first, Block::build(['ClaudeBot'], false, false));
        $this->assertStringNotContainsString('User-agent: GPTBot', $second);
        $this->assertStringContainsString('User-agent: ClaudeBot', $second);
    }

    public function testEmptyPolicyRestoresTheFile(): void
    {
        $with = Block::apply(self::PRESTASHOP, Block::build(['GPTBot'], false, false));
        $this->assertSame(rtrim(self::PRESTASHOP) . "\n", Block::apply($with, ''));
    }

    public function testBlockKeepsTheMerchantsOwnLines(): void
    {
        $own = "User-agent: *\nDisallow: /secret\n\n# my note\nUser-agent: BadBot\nDisallow: /\n";
        $result = Block::apply($own, Block::build(['GPTBot'], false, false));
        $this->assertStringContainsString('# my note', $result);
        $this->assertStringContainsString('Disallow: /secret', $result);
        $this->assertStringContainsString('User-agent: BadBot', Block::strip($result));
    }

    public function testIsPresent(): void
    {
        $block = Block::build(['GPTBot'], false, false);
        $this->assertFalse(Block::isPresent(self::PRESTASHOP, $block));
        $this->assertTrue(Block::isPresent(Block::apply(self::PRESTASHOP, $block), $block));
        $this->assertTrue(Block::isPresent(self::PRESTASHOP, ''));
    }
}
